const patch = "*** Begin Patch
*** Add File: tmp/spreadsheets/verify_4ausa_163/build_report.mjs
+import fs from "node:fs/promises";
+import path from "node:path";
+import { Workbook, SpreadsheetFile } from "@oai/artifact-tool";
+
+const root = String.raw`C:\Users\24243\Documents\Codex\2026-08-11\7-30-slack-plugin-slack-openai`;
+const targetCsv = path.join(root, "outputs", "019ff179-ce00-7621-9ae6-13daf0989ce8", "WooCommerce_完整改价_163_SKUs_复核后上传_2026-08-20.csv");
+const beforeCsv = String.raw`D:\下载文件\wc-product-export-20-8-2026-1787217563104.csv`;
+const outputDir = path.join(root, "outputs", "019ff179-ce00-7621-9ae6-13daf0989ce8");
+const outputPath = path.join(outputDir, "4Ausa_163_SKUs_改价实时核对_2026-08-21.xlsx");
+const previewDir = path.join(root, "tmp", "spreadsheets", "verify_4ausa_163", "preview");
+
+function rowsFromMatrix(matrix) {
+  const headers = matrix[0].map((v) => String(v ?? ""));
+  return matrix.slice(1).filter((row) => row.some((v) => v !== null && v !== "")).map((row) => {
+    const obj = {};
+    headers.forEach((h, i) => { obj[h] = row[i] ?? ""; });
+    return obj;
+  });
+}
+
+async function loadCsvRows(file, sheetName) {
+  const text = await fs.readFile(file, "utf8");
+  const wb = await Workbook.fromCSV(text, { sheetName });
+  const values = wb.worksheets.getItemAt(0).getUsedRange().values;
+  return rowsFromMatrix(values);
+}
+
+function money(value) {
+  if (value === null || value === undefined || String(value).trim() === "") return null;
+  const n = Number(value);
+  return Number.isFinite(n) ? n : null;
+}
+
+function liveMoney(value, minorUnit = 2) {
+  if (value === null || value === undefined || String(value).trim() === "") return null;
+  const n = Number(value);
+  return Number.isFinite(n) ? n / (10 ** minorUnit) : null;
+}
+
+async function fetchLiveProducts(ids) {
+  const map = new Map();
+  for (let i = 0; i < ids.length; i += 70) {
+    const batch = ids.slice(i, i + 70);
+    const url = `https://4ausa.com/wp-json/wc/store/v1/products?include=${batch.join(",")}&per_page=100`;
+    const response = await fetch(url, {
+      headers: { "User-Agent": "Mozilla/5.0 Codex price verification" },
+    });
+    if (!response.ok) throw new Error(`4Ausa API ${response.status}: ${await response.text()}`);
+    const products = await response.json();
+    for (const p of products) map.set(String(p.id), p);
+  }
+  return map;
+}
+
+const [targetRows, beforeRows] = await Promise.all([
+  loadCsvRows(targetCsv, "Target"),
+  loadCsvRows(beforeCsv, "Before"),
+]);
+
+if (targetRows.length !== 163) throw new Error(`Expected 163 target rows, received ${targetRows.length}`);
+const beforeById = new Map(beforeRows.map((r) => [String(r.ID), r]));
+const ids = targetRows.map((r) => String(r.ID));
+const liveById = await fetchLiveProducts(ids);
+
+const checkedAt = new Intl.DateTimeFormat("zh-CN", {
+  timeZone: "Asia/Shanghai",
+  year: "numeric", month: "2-digit", day: "2-digit",
+  hour: "2-digit", minute: "2-digit", second: "2-digit",
+  hour12: false,
+}).format(new Date());
+
+const results = targetRows.map((target, index) => {
+  const id = String(target.ID);
+  const before = beforeById.get(id);
+  const live = liveById.get(id);
+  const targetRegular = money(target["Regular price"]);
+  const targetSale = money(target["Sale price"]);
+  const beforeRegular = before ? money(before["Regular price"]) : null;
+
+  if (!live) {
+    return {
+      seq: index + 1, id, sku: String(target.SKU), name: before?.Name || "",
+      beforeRegular, liveRegular: null, liveSale: null,
+      targetRegular, targetSale, status: "网站未返回", note: "实时商品接口未返回该 ID", url: "",
+    };
+  }
+
+  const unit = Number(live.prices?.currency_minor_unit ?? 2);
+  const liveRegular = liveMoney(live.prices?.regular_price, unit);
+  const liveSale = liveMoney(live.prices?.sale_price, unit);
+  const regularOk = liveRegular !== null && Math.abs(liveRegular - targetRegular) < 0.001;
+  const saleOk = liveSale !== null && Math.abs(liveSale - targetSale) < 0.001;
+  const issues = [];
+  if (!regularOk) issues.push(`目标原价 $${targetRegular?.toFixed(2)}，实时 $${liveRegular?.toFixed(2) ?? "空"}`);
+  if (!saleOk) issues.push(`目标优惠价 $${targetSale?.toFixed(2)}，实时 $${liveSale?.toFixed(2) ?? "空"}`);
+  return {
+    seq: index + 1, id, sku: String(target.SKU), name: String(live.name || before?.Name || "").replaceAll("&#215;", "×"),
+    beforeRegular, liveRegular, liveSale, targetRegular, targetSale,
+    status: regularOk && saleOk ? "成功" : "价格不一致",
+    note: issues.join("；"), url: String(live.permalink || ""),
+  };
+});
+
+const priority = { "价格不一致": 0, "网站未返回": 1, "成功": 2 };
+const sorted = [...results].sort((a, b) => (priority[a.status] - priority[b.status]) || (a.seq - b.seq));
+const successCount = results.filter((r) => r.status === "成功").length;
+const mismatchCount = results.filter((r) => r.status === "价格不一致").length;
+const missingCount = results.filter((r) => r.status === "网站未返回").length;
+
+const workbook = Workbook.create();
+const summary = workbook.worksheets.add("核对总览");
+const details = workbook.worksheets.add("价格核对明细");
+summary.showGridLines = false;
+details.showGridLines = false;
+
+// Detail sheet: requested price presentation order is preserved exactly.
+details.getRange("A1:J1").values = [[
+  "上传序号", "商品ID", "SKU", "商品名称",
+  "原价（未改）", "原价（已改）", "优惠价（如有）",
+  "核对结果", "异常说明", "前台链接",
+]];
+const detailValues = sorted.map((r) => [
+  r.seq, r.id, r.sku, r.name,
+  r.beforeRegular, r.liveRegular, r.liveSale,
+  r.status, r.note, r.url,
+]);
+details.getRange(`A2:J${detailValues.length + 1}`).values = detailValues;
+details.getRange("K1").values = [["原价变动"]];
+details.getRange("K2").formulas = [["=F2-E2"]];
+details.getRange(`K2:K${detailValues.length + 1}`).fillDown();
+
+details.getRange("A1:K1").format = {
+  fill: "#17324D",
+  font: { bold: true, color: "#FFFFFF", size: 10 },
+  verticalAlignment: "center",
+  wrapText: true,
+  borders: { preset: "doubleBottom", style: "medium", color: "#17324D" },
+};
+details.getRange("A1:K1").format.rowHeight = 34;
+details.getRange(`A2:K${detailValues.length + 1}`).format = {
+  font: { color: "#243746", size: 9 },
+  verticalAlignment: "center",
+  borders: { insideHorizontal: { style: "thin", color: "#E6EBEF" } },
+};
+details.getRange(`E2:G${detailValues.length + 1}`).format.numberFormat = "$0.00";
+details.getRange(`K2:K${detailValues.length + 1}`).format.numberFormat = "$0.00;[Red]-$0.00;$0.00";
+details.getRange(`A2:B${detailValues.length + 1}`).format.horizontalAlignment = "center";
+details.getRange(`E2:H${detailValues.length + 1}`).format.horizontalAlignment = "center";
+details.getRange(`A2:K${detailValues.length + 1}`).format.rowHeight = 22;
+
+// Practical widths for 163-row review.
+const widths = { A: 10, B: 10, C: 24, D: 66, E: 15, F: 15, G: 16, H: 14, I: 44, J: 54, K: 13 };
+for (const [col, width] of Object.entries(widths)) details.getRange(`${col}:${col}`).format.columnWidth = width;
+details.getRange(`D2:D${detailValues.length + 1}`).format.wrapText = false;
+details.getRange(`I2:J${detailValues.length + 1}`).format.wrapText = false;
+details.freezePanes.freezeRows(1);
+details.freezePanes.freezeColumns(3);
+const table = details.tables.add(`A1:K${detailValues.length + 1}`, true, "PriceVerificationTable");
+table.style = "TableStyleMedium2";
+table.showBandedRows = true;
+table.showFilterButton = true;
+
+const statusRange = details.getRange(`H2:H${detailValues.length + 1}`);
+statusRange.conditionalFormats.add("containsText", { text: "成功", format: { fill: "#DFF2E3", font: { bold: true, color: "#24733E" } } });
+statusRange.conditionalFormats.add("containsText", { text: "不一致", format: { fill: "#FCE1DF", font: { bold: true, color: "#B42318" } } });
+statusRange.conditionalFormats.add("containsText", { text: "未返回", format: { fill: "#FFF1C2", font: { bold: true, color: "#8A5A00" } } });
+
+// Summary sheet with formula-driven KPIs.
+summary.getRange("A1:H1").merge();
+summary.getRange("A1").values = [["4Ausa 163 个 SKU 改价实时核对"]];
+summary.getRange("A1:H1").format = {
+  fill: "#17324D", font: { bold: true, color: "#FFFFFF", size: 20 },
+  horizontalAlignment: "left", verticalAlignment: "center",
+};
+summary.getRange("A1:H1").format.rowHeight = 46;
+summary.getRange("A3:H3").merge();
+summary.getRange("A3").values = [[`核对时间：${checkedAt}（Asia/Shanghai）｜实时来源：4Ausa WooCommerce Store API`]];
+summary.getRange("A3:H3").format = { fill: "#EDF3F7", font: { color: "#526674", size: 10 } };
+
+summary.getRange("A5:B10").values = [
+  ["指标", "数量"],
+  ["上传文件 SKU", null],
+  ["价格完全一致", null],
+  ["价格不一致", null],
+  ["网站未返回", null],
+  ["原价发生变化", null],
+];
+summary.getRange("B6").formulas = [["=COUNTA('价格核对明细'!A2:A164)"]];
+summary.getRange("B7").formulas = [["=COUNTIF('价格核对明细'!H2:H164,\"成功\")"]];
+summary.getRange("B8").formulas = [["=COUNTIF('价格核对明细'!H2:H164,\"价格不一致\")"]];
+summary.getRange("B9").formulas = [["=COUNTIF('价格核对明细'!H2:H164,\"网站未返回\")"]];
+summary.getRange("B10").formulas = [["=COUNTIF('价格核对明细'!K2:K164,\"<>0\")"]];
+summary.getRange("A5:B5").format = { fill: "#2B5B73", font: { bold: true, color: "#FFFFFF" } };
+summary.getRange("A6:B10").format = { borders: { insideHorizontal: { style: "thin", color: "#DDE5EA" } }, font: { color: "#243746" } };
+summary.getRange("B6:B10").format = { font: { bold: true, size: 15 }, horizontalAlignment: "center", numberFormat: "0" };
+summary.getRange("A5:B10").format.rowHeight = 29;
+summary.getRange("A:A").format.columnWidth = 24;
+summary.getRange("B:B").format.columnWidth = 14;
+
+summary.getRange("D5:H5").merge();
+summary.getRange("D5").values = [["核对结论"]];
+summary.getRange("D5:H5").format = { fill: "#2B5B73", font: { bold: true, color: "#FFFFFF" } };
+summary.getRange("D6:H9").merge();
+const conclusion = mismatchCount === 0 && missingCount === 0
+  ? `全部 ${successCount} 个商品的当前原价和优惠价都与上传文件一致。可判定本次 163 个 SKU 批量改价成功。`
+  : `成功 ${successCount} 个；价格不一致 ${mismatchCount} 个；网站未返回 ${missingCount} 个。请先筛选明细表“核对结果”列处理异常。`;
+summary.getRange("D6").values = [[conclusion]];
+summary.getRange("D6:H9").format = {
+  fill: mismatchCount === 0 && missingCount === 0 ? "#E1F2E5" : "#FFF1C2",
+  font: { bold: true, color: mismatchCount === 0 && missingCount === 0 ? "#24733E" : "#8A5A00", size: 13 },
+  wrapText: true, verticalAlignment: "center",
+  borders: { preset: "outside", style: "thin", color: "#C7D6CC" },
+};
+summary.getRange("D:D").format.columnWidth = 17;
+summary.getRange("E:H").format.columnWidth = 15;
+
+summary.getRange("A13:H13").merge();
+summary.getRange("A13").values = [["阅读方式"]];
+summary.getRange("A13:H13").format = { fill: "#E8EEF2", font: { bold: true, color: "#17324D" } };
+summary.getRange("A14:H17").merge();
+summary.getRange("A14").values = [[
+  "明细表按照你要求的顺序展示：原价（未改） → 原价（已改） → 优惠价（如有）。\n" +
+  "‘核对结果’对比的是当前实时价格与本次 163 SKU 上传文件；异常项自动排在明细最上方。\n" +
+  "原价（未改）来自 2026-08-20 上传前的 WooCommerce 商品导出；实时价格来自 4Ausa 当前公开商品接口。"
+]];
+summary.getRange("A14:H17").format = { wrapText: true, verticalAlignment: "top", font: { color: "#526674", size: 10 } };
+summary.freezePanes.freezeRows(3);
+
+await fs.mkdir(outputDir, { recursive: true });
+await fs.mkdir(previewDir, { recursive: true });
+
+const detailCheck = await workbook.inspect({
+  kind: "table", sheetId: "价格核对明细", range: "A1:K12",
+  include: "values,formulas", tableMaxRows: 12, tableMaxCols: 11, maxChars: 8000,
+});
+const formulaErrors = await workbook.inspect({
+  kind: "match", searchTerm: "#REF!|#DIV/0!|#VALUE!|#NAME\\?|#N/A",
+  options: { useRegex: true, maxResults: 100 }, summary: "final formula error scan", maxChars: 3000,
+});
+console.log(detailCheck.ndjson);
+console.log(formulaErrors.ndjson);
+
+const summaryPreview = await workbook.render({ sheetName: "核对总览", range: "A1:H17", scale: 1.4, format: "png" });
+await fs.writeFile(path.join(previewDir, "summary.png"), new Uint8Array(await summaryPreview.arrayBuffer()));
+const detailPreview = await workbook.render({ sheetName: "价格核对明细", range: "A1:K18", scale: 1.0, format: "png" });
+await fs.writeFile(path.join(previewDir, "details.png"), new Uint8Array(await detailPreview.arrayBuffer()));
+
+const output = await SpreadsheetFile.exportXlsx(workbook);
+await output.save(outputPath);
+
+console.log(JSON.stringify({
+  outputPath, checkedAt, total: results.length, successCount, mismatchCount, missingCount,
+  liveReturned: liveById.size,
+}, null, 2));
*** End Patch";
const result = await tools.apply_patch(patch);
text(result);

